// Generates supabase/dev_seed_public.sql from src/data/enactusData.js
//
//   node scripts/generate-dev-seed.mjs
//
// DEV ONLY. It loads the current mock content (committees, board, events, news,
// FAQ, sponsorship tiers, alumni) into the database so the public pages can be
// switched from mock data to Supabase without changing what visitors see.
// The mock content contains placeholder people / links: replace them from the
// dashboard before launch. Never run the generated file on production.

import { mkdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const dataFile = path.join(root, 'src', 'data', 'enactusData.js');
const outFile = path.join(root, 'supabase', 'dev_seed_public.sql');

const data = await import(pathToFileURL(dataFile).href);
const {
  committeesData = [],
  boardMembers = [],
  eventsData = [],
  newsArticles = [],
  faqList = [],
  sponsorshipTiers = [],
  alumniData = [],
} = data;

// ---------- SQL helpers ----------
const q = (v) => (v === null || v === undefined || v === '' ? 'null' : `'${String(v).replace(/'/g, "''")}'`);
const j = (v) => `'${JSON.stringify(v ?? null).replace(/'/g, "''")}'::jsonb`;
const n = (v) => (Number.isFinite(v) ? String(v) : 'null');
const ACTIVE_SEASON = '(select id from public.seasons where is_active limit 1)';
const committeeId = (slug) => `(select id from public.committees where slug = ${q(slug)})`;

// ---------- Arabic date / time parsing ----------
const MONTHS = {
  يناير: 1, فبراير: 2, مارس: 3, أبريل: 4, ابريل: 4, مايو: 5, يونيو: 6,
  يوليو: 7, أغسطس: 8, اغسطس: 8, سبتمبر: 9, أكتوبر: 10, اكتوبر: 10, نوفمبر: 11, ديسمبر: 12,
};
function parseArabicDate(text) {
  const m = String(text ?? '').match(/(\d{1,2})\s+([\u0600-\u06FF]+)\s+(\d{4})/);
  if (!m || !MONTHS[m[2]]) return null;
  return { y: Number(m[3]), mo: MONTHS[m[2]], d: Number(m[1]) };
}
function parseTimes(text) {
  const out = [];
  for (const m of String(text ?? '').matchAll(/(\d{1,2}):(\d{2})\s*(صباحاً|صباحا|مساءً|مساءا|مساء|ص|م)?/g)) {
    let h = Number(m[1]);
    const suffix = m[3] ?? '';
    if (suffix.startsWith('م') && h < 12) h += 12;
    if (suffix.startsWith('ص') && h === 12) h = 0;
    out.push({ h, mi: Number(m[2]) });
  }
  return out;
}
const pad = (x) => String(x).padStart(2, '0');
// Cairo wall-clock time -> timestamptz, evaluated by Postgres (handles Egypt DST).
function cairoTs({ y, mo, d }, h = 10, mi = 0, addDays = 0) {
  const dt = new Date(Date.UTC(y, mo - 1, d + addDays));
  const date = `${dt.getUTCFullYear()}-${pad(dt.getUTCMonth() + 1)}-${pad(dt.getUTCDate())}`;
  return `(timestamp '${date} ${pad(h)}:${pad(mi)}:00' at time zone 'Africa/Cairo')`;
}

const COMMITTEE_STYLE = {
  pm: { color: '#16A34A', icon: 'sprout' },
  multimedia: { color: '#7C3AED', icon: 'clapperboard' },
  pr: { color: '#2563EB', icon: 'handshake' },
  oc: { color: '#EA580C', icon: 'calendar-check' },
  hr: { color: '#0D9488', icon: 'users' },
  presentation: { color: '#DC2626', icon: 'mic' },
  social: { color: '#DB2777', icon: 'megaphone' },
};
const MEDIA_TEAM = new Set(['multimedia', 'social']);
const PLACEHOLDER_COMMITTEES = ['media', 'finance'];

const out = [];
const push = (s = '') => out.push(s);

push('-- =====================================================================');
push('-- DEV ONLY: generated by scripts/generate-dev-seed.mjs from src/data/enactusData.js');
push('-- Contains MOCK people and links (board, heads, alumni). Replace them from the');
push('-- dashboard before launch. Do NOT run this on production.');
push('-- Re-running is safe: it replaces its own rows.');
push('-- =====================================================================');
push('begin;');
push();

// ---------- committees ----------
push('-- Committees (upsert by slug) + drop the two placeholder committees from the first seed');
push(`delete from public.committees c where c.slug in (${PLACEHOLDER_COMMITTEES.map(q).join(', ')})`);
push('  and not exists (select 1 from public.memberships m where m.committee_id = c.id)');
push('  and not exists (select 1 from public.tasks t where t.committee_id = c.id);');
committeesData.forEach((c, i) => {
  const style = COMMITTEE_STYLE[c.slug] ?? { color: '#C9A227', icon: null };
  const content = {
    ar: {
      brief: c.brief, mascot: c.mascotDesc, duties: c.duties ?? [], skillsRequired: c.skillsRequired ?? [],
      skillsGained: c.skillsGained ?? [], activeProjects: c.activeProjects ?? [], quote: c.quote,
    },
    en: {},
  };
  push(`insert into public.committees (slug, code, name_ar, name_en, description_ar, color, icon, sort_order, is_public, is_media_team, content)`);
  push(`values (${q(c.slug)}, ${q(c.code)}, ${q(c.arabicName)}, ${q(c.name)}, ${q(c.description)}, ${q(style.color)}, ${q(style.icon)}, ${i + 1}, true, ${MEDIA_TEAM.has(c.slug)}, ${j(content)})`);
  push('on conflict (slug) do update set');
  push('  code = excluded.code, name_ar = excluded.name_ar, name_en = excluded.name_en, description_ar = excluded.description_ar,');
  push('  color = excluded.color, icon = excluded.icon, sort_order = excluded.sort_order, is_public = excluded.is_public,');
  push('  is_media_team = excluded.is_media_team, content = excluded.content;');
});
push();

// ---------- team_public: heads, board, alumni ----------
push('-- Team: committee heads, board, alumni (curated public rows without a linked account)');
push(`delete from public.team_public where kind in ('head', 'board', 'alumni') and user_id is null;`);
committeesData.forEach((c, i) => {
  push(`insert into public.team_public (season_id, committee_id, kind, name_ar, position_ar, position_en, photo_url, sort_order, is_visible)`);
  push(`values (${ACTIVE_SEASON}, ${committeeId(c.slug)}, 'head', ${q(c.headName)}, ${q(`رئيس لجنة ${c.arabicName}`)}, ${q(c.headRole)}, ${q(c.headAvatar)}, ${i + 1}, true);`);
});
boardMembers.forEach((b, i) => {
  const links = {};
  if (b.linkedin) links.linkedin = b.linkedin;
  if (b.facebook) links.facebook = b.facebook;
  push(`insert into public.team_public (season_id, kind, name_ar, position_ar, position_en, faculty_ar, bio_ar, photo_url, links, sort_order, is_visible)`);
  push(`values (${ACTIVE_SEASON}, 'board', ${q(b.name)}, ${q(b.role)}, ${q(b.englishRole)}, ${q(b.faculty)}, ${q(b.bio)}, ${q(b.image)}, ${j(links)}, ${i + 1}, true);`);
});
alumniData.forEach((a, i) => {
  push(`insert into public.team_public (kind, name_ar, position_ar, current_position_ar, quote_ar, photo_url, sort_order, is_visible)`);
  push(`values ('alumni', ${q(a.name)}, ${q(a.formerRole)}, ${q(a.currentPosition)}, ${q(a.quote)}, ${q(a.image)}, ${i + 1}, true);`);
});
push();

// ---------- events ----------
push('-- Events (upsert by slug). upcoming -> published, past -> completed');
const warnings = [];
eventsData.forEach((e) => {
  const date = parseArabicDate(e.date);
  if (!date) {
    warnings.push(`event "${e.slug}": could not parse date "${e.date}"`);
    return;
  }
  const times = parseTimes(e.time);
  const start = times[0] ?? { h: 10, mi: 0 };
  const end = times[1];
  const extraDay = /يومين/.test(e.time ?? '') ? 1 : 0;
  const schedule = (e.schedule ?? []).map((s) => ({ time_ar: s.time, activity_ar: s.activity }));
  const status = e.status === 'past' ? 'completed' : 'published';
  push(`insert into public.events (season_id, slug, title_ar, title_en, description_ar, brief_ar, venue_ar, starts_at, ends_at, status, cover_url, is_public, registration_open, category_ar, time_label_ar, schedule, partner_names)`);
  push(`values (${ACTIVE_SEASON}, ${q(e.slug)}, ${q(e.title)}, ${q(e.englishTitle)}, ${q(e.description)}, ${q(e.brief)}, ${q(e.location)}, ${cairoTs(date, start.h, start.mi)}, ${end ? cairoTs(date, end.h, end.mi, extraDay) : 'null'}, ${q(status)}, ${q(e.image)}, true, false, ${q(e.category)}, ${q(e.time)}, ${j(schedule)}, ${j(e.partnersInvolved ?? [])})`);
  push('on conflict (slug) do update set');
  push('  title_ar = excluded.title_ar, title_en = excluded.title_en, description_ar = excluded.description_ar, brief_ar = excluded.brief_ar,');
  push('  venue_ar = excluded.venue_ar, starts_at = excluded.starts_at, ends_at = excluded.ends_at, status = excluded.status, cover_url = excluded.cover_url,');
  push('  is_public = excluded.is_public, category_ar = excluded.category_ar, time_label_ar = excluded.time_label_ar,');
  push('  schedule = excluded.schedule, partner_names = excluded.partner_names;');
});
push();

// ---------- news ----------
push('-- News (upsert by slug)');
newsArticles.forEach((a) => {
  const date = parseArabicDate(a.date);
  if (!date) warnings.push(`news "${a.slug}": could not parse date "${a.date}"`);
  const published = date ? cairoTs(date, 12, 0) : 'now()';
  push(`insert into public.news_posts (slug, title_ar, excerpt_ar, body_ar, cover_url, category_ar, is_published, published_at)`);
  push(`values (${q(a.slug)}, ${q(a.title)}, ${q(a.excerpt)}, ${q(a.content)}, ${q(a.image)}, ${q(a.category)}, true, ${published})`);
  push('on conflict (slug) do update set');
  push('  title_ar = excluded.title_ar, excerpt_ar = excluded.excerpt_ar, body_ar = excluded.body_ar, cover_url = excluded.cover_url,');
  push('  category_ar = excluded.category_ar, is_published = excluded.is_published, published_at = excluded.published_at;');
});
push();

// ---------- FAQ ----------
push('-- FAQ (replaced as a whole)');
push('delete from public.faqs;');
faqList.forEach((f, i) => {
  push(`insert into public.faqs (question_ar, answer_ar, sort_order) values (${q(f.q)}, ${q(f.a)}, ${i + 1});`);
});
push();

// ---------- sponsorship tiers ----------
const tierOf = (t) => {
  const s = `${t.englishName ?? ''} ${t.name ?? ''}`.toLowerCase();
  if (s.includes('diamond') || s.includes('ماس')) return 'platinum';
  if (s.includes('gold') || s.includes('ذهب')) return 'gold';
  if (s.includes('silver') || s.includes('فض')) return 'silver';
  return 'custom';
};
push('-- Sponsorship tiers (replaced by name). The public label replaces a price on purpose.');
if (sponsorshipTiers.length) {
  push(`delete from public.sponsorship_packages where name_en in (${sponsorshipTiers.map((t) => q(t.englishName ?? t.name)).join(', ')});`);
}
sponsorshipTiers.forEach((t, i) => {
  push(`insert into public.sponsorship_packages (season_id, name_ar, name_en, tier, price, tagline_ar, badge_ar, is_featured, benefits_ar, is_public, is_active, sort_order)`);
  push(`values (${ACTIVE_SEASON}, ${q(t.name)}, ${q(t.englishName ?? t.name)}, ${q(tierOf(t))}, null, ${q(t.price)}, ${q(t.badge)}, ${t.featured ? 'true' : 'false'}, ${j(t.perks ?? [])}, true, true, ${i + 1});`);
});
push();

// ---------- partners (names only; logos are uploaded from the dashboard) ----------
const partnerNames = [...new Set(eventsData.flatMap((e) => e.partnersInvolved ?? []))];
push('-- Partners found in the events (names only; add logos / websites from the dashboard)');
if (partnerNames.length) {
  push(`delete from public.partners where company_id is null and name_ar in (${partnerNames.map(q).join(', ')});`);
}
partnerNames.forEach((name, i) => {
  const kind = name.includes('جامعة') ? 'strategic' : 'sponsor';
  push(`insert into public.partners (name_ar, kind, sort_order, is_visible) values (${q(name)}, ${q(kind)}, ${i + 1}, true);`);
});
push();
push('commit;');

mkdirSync(path.dirname(outFile), { recursive: true });
writeFileSync(outFile, `${out.join('\n')}\n`, 'utf8');

console.log(`Wrote ${path.relative(root, outFile)}`);
console.log(
  `committees=${committeesData.length} board=${boardMembers.length} events=${eventsData.length} news=${newsArticles.length} faq=${faqList.length} tiers=${sponsorshipTiers.length} alumni=${alumniData.length} partners=${partnerNames.length}`,
);
if (warnings.length) {
  console.warn('WARNINGS:\n - ' + warnings.join('\n - '));
  process.exitCode = 1;
}
